":"netDebtYears","anchors":[{"value":0.5,"share":1},{"value":1,"share":0.6},{"value":3,"share":0.2},{"value":5,"share":0}],"liftedByWealthRunway":false,"warning":{"text":"Elevated total debt","severe":{"text":"High total debt","when":"above","threshold":3}}},{"name":"SavingsRate","maxPoints":30,"measure":"savingsRate","anchors":[{"value":-0.10,"share":0},{"value":0,"share":0.2},{"value":0.10,"share":0.6},{"value":0.20,"share":1}],"liftedByWealthRunway":true,"warning":{"text":"Low savings rate","severe":{"text":"Negative savings rate","when":"below","threshold":0}}},{"name":"Impatience","maxPoints":5,"measure":"impatienceLevel","anchors":[{"value":1,"share":1},{"value":2,"share":0.8},{"value":3,"share":0.6},{"value":4,"share":0.2},{"value":5,"share":0}],"liftedByWealthRunway":false,"warning":{"text":"High impatience"}}],"points":"points = maxPoints x share x solvencyCap, rounded half up per factor (first to 6 decimals, then to an integer); score = sum of the factor points","warningShare":0.6,"factorWarning":"a factor whose points before the solvency cap (maxPoints x share, rounded) are below warningShare x maxPoints gets its warning; the severe text replaces it when the factor's measure meets the severe condition","solvencyCap":{"measure":"netDebtYears","anchors":[{"value":5,"share":1},{"value":15,"share":0}],"effect":"multiplies the points of every factor","warning":"Extreme total debt when solvencyCap < 1","appliedRule":"SOLVENCY_CAP","appliedRuleCondition":"solvencyCap < 1"},"wealthRunway":{"measure":"runwayYears","anchors":[{"value":0,"share":0},{"value":25,"share":1}],"effect":"floor for the share of InstallmentToIncome and SavingsRate: share = max(own share, runway share)","appliedRule":"WEALTH_RUNWAY","appliedRuleCondition":"no SOLVENCY_CAP, runwayYears >= 5 and the score is higher than the same calculation with a runway share of 0"},"otherWarnings":[{"text":"Installment below interest","condition":"netDebt > 0 and monthly debt payment < 0.035 x netDebt"},{"text":"Expenses look too low","condition":"monthly expenses < 0.10 x monthly income"},{"text":"Installment without debt","condition":"monthly debt payment > 0 and total debt = 0"},{"text":"Installment exceeds total debt","condition":"total debt > 0 and monthly debt payment > total debt"}],"warningOrder":"factor warnings in factor order, then the solvency cap warning, then otherWarnings in this order; no duplicates","appliedRuleNote":"appliedRule is a label only (SOLVENCY_CAP first, then WEALTH_RUNWAY, otherwise null); the score is always the sum of the factor points"}
